gpk(){return"\u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gtF(){return"\u064a\u0639\u0631\u0636 \u0639\u062f\u062f \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u062d\u0635\u0627\u0626\u064a\u0627\u062a"},
